sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var taskQuery = 'active=true^trade_case_id=' + current.sys_id; // Query to all active task related to the respective case ID
    var grCustodyTask = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_task');
    grCustodyTask.addEncodedQuery(taskQuery);
    grCustodyTask.query();
    while (grCustodyTask.next()) {
        if (grCustodyTask.assigned_to) { // Updating State of Task to "Closed Complete if Task is assigned to any individual"
            grCustodyTask.state = 3;
            grCustodyTask.work_notes = 'Task automatically closed by System due to case closure'; // Adding the comment on custody task when it's get closed by FOL event.
			grCustodyTask.setValue('sub_trade_task_type', 'GHSS Interim Update');//fix for MSSCUSTODY-4307
        } else {
            grCustodyTask.state = 7; // Updating State of Task to "Cancelled" if Task is NOT assigned to any individual
			//fix for MSSCUSTODY-4307
			grCustodyTask.setValue('sub_trade_task_type', 'GHSS Interim Update');
            grCustodyTask.work_notes = 'Custody Task is cancelled due to case closure/GHSS interim update'; //Adding the comment on custody task when it's get cancelled by FOL event.
        }
        grCustodyTask.update();
    }


})(current, previous);
